        for j in x1:
            for i in range(r1+1,h):
                if out[i][j]==bg: out[i][j]=fill
        for j in x2:
            for i in range(r2):
                if out[i][j]==bg: out[i][j]=fill
        for i,row in enumerate(grid):
            for j,v in enumerate(row):
                if v==fill: out[i][j]=4
    return out
